import math
import shutil
import filecmp

import openpyxl

DEMAND_PATH = '/root/hvac_demand_sheet.xlsx'
EXISTING_PLAN_PATH = '/root/hvac_existing_plan.xlsx'
SCHEDULE_PLAN_PATH = '/root/hvac_schedule_plan.xlsx'
SUMMARY_PATH = '/root/hvac_schedule_summary.txt'

PHASE_START = 8
PHASE_END = 56
INITIAL_TOTAL_PHASE8 = 1138.66

HEADERS = [
    'Phase',
    'Days Worked',
    'Scheduled Demand (Std Hrs)',
    'Weekly Capacity (Std Hrs)',
    'Start of Phase Past Due (Std Hrs)',
    'End of Phase Backlog/Buffer (Std Hrs)',
    'Overtime Hours',
]


def _find_demand_columns(ws):
    """Return (phase_col, demand_col, header_row) from a worksheet.

    Looks for a row containing 'Phase' and 'HVAC Ductwork Demand' (partial, case-insensitive).
    """
    phase_col = None
    demand_col = None
    header_row = None

    for r in range(1, ws.max_row + 1):
        row_values = [(c, ws.cell(r, c).value) for c in range(1, ws.max_column + 1)]
        texts = []
        for c, v in row_values:
            if isinstance(v, str):
                texts.append((c, v.strip()))

        if not texts:
            continue

        # identify candidate columns
        for c, t in texts:
            if 'phase' == t.lower():
                phase_col = c
                header_row = r
            if 'hvac ductwork demand' in t.lower():
                demand_col = c
                header_row = r

        if header_row is not None and phase_col is not None and demand_col is not None:
            return phase_col, demand_col, header_row

    raise RuntimeError('Could not find demand header row/columns (Phase, HVAC Ductwork Demand).')


def read_demand_map():
    wb = openpyxl.load_workbook(DEMAND_PATH, data_only=True)
    if 'Install' not in wb.sheetnames:
        raise RuntimeError(f"Expected sheet 'Install' in {DEMAND_PATH}, found {wb.sheetnames}")
    ws = wb['Install']

    phase_col, demand_col, header_row = _find_demand_columns(ws)

    demand_map = {}
    for r in range(header_row + 1, ws.max_row + 1):
        phase_val = ws.cell(r, phase_col).value
        demand_val = ws.cell(r, demand_col).value
        if phase_val is None and demand_val is None:
            continue

        try:
            phase = int(phase_val)
        except Exception:
            continue

        if phase < PHASE_START or phase > PHASE_END:
            continue

        if demand_val is None:
            raise RuntimeError(f'Missing demand value for phase {phase} at row {r}')
        demand_map[phase] = float(demand_val)

    missing = [p for p in range(PHASE_START, PHASE_END + 1) if p not in demand_map]
    if missing:
        raise RuntimeError(f'Missing demand for phases: {missing}')

    return demand_map


def build_results(demand_map):
    phases = list(range(PHASE_START, PHASE_END + 1))
    results = []

    first_phase = True
    prev_end_backlog = None

    # keep exact values too (for validation)
    exact = []

    for phase in phases:
        demand = demand_map[phase]

        if first_phase:
            calc_start = INITIAL_TOTAL_PHASE8 - demand
            first_phase = False
        else:
            calc_start = prev_end_backlog

        start_past_due = max(0.0, calc_start)

        # Choose Days Worked
        if start_past_due > 0.01:
            # Try 5 first, then 6
            if calc_start + demand - (35 * 5) <= 0:
                days_worked = 5
            elif calc_start + demand - (35 * 6) <= 0:
                days_worked = 6
            else:
                days_worked = 6
        else:
            # No past due
            if demand <= 140:
                days_worked = 4
            else:
                days_worked = 5

        weekly_capacity = 35 * days_worked
        end_backlog = calc_start + demand - weekly_capacity
        overtime = 10 * max(0, days_worked - 4)

        results.append({
            'Phase': phase,
            'Days Worked': days_worked,
            'Scheduled Demand (Std Hrs)': round(demand, 2),
            'Weekly Capacity (Std Hrs)': weekly_capacity,
            'Start of Phase Past Due (Std Hrs)': round(start_past_due, 2),
            'End of Phase Backlog/Buffer (Std Hrs)': round(end_backlog, 2),
            'Overtime Hours': overtime,
        })
        exact.append({
            'phase': phase,
            'calc_start': calc_start,
            'demand': demand,
            'weekly_capacity': weekly_capacity,
            'start_past_due': start_past_due,
            'end_backlog': end_backlog,
            'days_worked': days_worked,
        })

        prev_end_backlog = end_backlog

    # Verify Phase 8 initial condition (using exact values)
    p8 = exact[0]
    assert p8['phase'] == PHASE_START
    phase8_sum = p8['start_past_due'] + p8['demand']
    if not math.isclose(phase8_sum, INITIAL_TOTAL_PHASE8, rel_tol=0.0, abs_tol=1e-6):
        raise RuntimeError(
            f"Phase 8 check failed: start_past_due + demand = {phase8_sum}, expected {INITIAL_TOTAL_PHASE8}"
        )

    return results, exact


def print_preview(results):
    print('\nFirst 5 rows:')
    for r in results[:5]:
        print(r)
    print('\nLast 5 rows:')
    for r in results[-5:]:
        print(r)


def find_first_weeks(results):
    first_5 = 'N/A'
    first_4 = 'N/A'
    for r in results:
        if first_5 == 'N/A' and r['Days Worked'] == 5:
            first_5 = str(r['Phase'])
        if first_4 == 'N/A' and r['Days Worked'] == 4:
            first_4 = str(r['Phase'])
    return first_5, first_4


def write_excel_files(results):
    # Write /root/hvac_existing_plan.xlsx (overwrite)
    wb_plan = openpyxl.Workbook()
    ws_plan = wb_plan.active
    ws_plan.title = 'Plan'
    ws_plan.append(HEADERS)
    for r in results:
        ws_plan.append([r[h] for h in HEADERS])
    wb_plan.save(EXISTING_PLAN_PATH)

    # Write /root/hvac_schedule_plan.xlsx (copy)
    shutil.copy(EXISTING_PLAN_PATH, SCHEDULE_PLAN_PATH)


def _summary_line(first_5, first_4):
    # Keep <=60 words, <=3 sentences. Use 1 sentence.
    if first_5 != 'N/A' and first_4 != 'N/A':
        return (
            f"The crew works 6-day weeks to clear the initial backlog, steps down to 5-day weeks at Phase {first_5}, "
            f"and to 4-day weeks at Phase {first_4} as demand normalizes; overtime drops from 20 to 10 to 0 hours per week."
        )
    if first_5 != 'N/A' and first_4 == 'N/A':
        return (
            f"The crew works 6-day weeks to clear the initial backlog and steps down to 5-day weeks at Phase {first_5}; "
            f"no 4-day weeks occur (First_Week_4_Days: N/A) and overtime drops from 20 to 10 hours per week."
        )
    if first_5 == 'N/A' and first_4 != 'N/A':
        return (
            f"The crew does not use 5-day weeks (First_Week_5_Days: N/A) and first reaches 4-day weeks at Phase {first_4}; "
            f"overtime is 20 hours per week until then."
        )
    return (
        "The crew works 6-day weeks throughout (First_Week_5_Days: N/A; First_Week_4_Days: N/A), "
        "so overtime remains 20 hours per week."  # one sentence
    )


def write_summary(results):
    first_5, first_4 = find_first_weeks(results)
    summary = _summary_line(first_5, first_4)

    with open(SUMMARY_PATH, 'w') as f:
        f.write(f'First_Week_5_Days: {first_5}\n')
        f.write(f'First_Week_4_Days: {first_4}\n')
        f.write(f'Summary: {summary}\n')


def validate_outputs(results, exact):
    # 1. Validate schedule plan workbook
    wb = openpyxl.load_workbook(SCHEDULE_PLAN_PATH, data_only=True)
    if wb.sheetnames != ['Plan']:
        raise RuntimeError(f"Expected only sheet ['Plan'], found {wb.sheetnames}")

    ws = wb['Plan']

    # Headers
    headers_read = [ws.cell(1, c).value for c in range(1, len(HEADERS) + 1)]
    if headers_read != HEADERS:
        raise RuntimeError(f'Header mismatch. Read={headers_read} Expected={HEADERS}')

    # Row counts
    expected_rows = (PHASE_END - PHASE_START + 1)
    data_rows = ws.max_row - 1
    if data_rows != expected_rows:
        raise RuntimeError(f'Expected {expected_rows} data rows, found {data_rows}')

    # Phases and days worked set
    for i, phase in enumerate(range(PHASE_START, PHASE_END + 1), start=2):
        v_phase = ws.cell(i, 1).value
        if int(v_phase) != phase:
            raise RuntimeError(f'Phase mismatch at row {i}: got {v_phase}, expected {phase}')
        days = int(ws.cell(i, 2).value)
        if days not in (4, 5, 6):
            raise RuntimeError(f'Invalid Days Worked at row {i}: {days}')

    # Phase 8 check (Start Past Due + Demand == 1138.66)
    phase8_start = float(ws.cell(2, 5).value)
    phase8_demand = float(ws.cell(2, 3).value)
    if not math.isclose(phase8_start + phase8_demand, INITIAL_TOTAL_PHASE8, rel_tol=0.0, abs_tol=1e-2):
        raise RuntimeError(
            f'Phase 8 sum mismatch: {phase8_start}+{phase8_demand}={phase8_start+phase8_demand} expected {INITIAL_TOTAL_PHASE8}'
        )

    # Spot-check backlog formula vs exact recomputation (rounded to 2 decimals in sheet)
    spot_phases = [8, 9, 15, 25, 40, 56]
    exact_by_phase = {e['phase']: e for e in exact}
    for p in spot_phases:
        row = (p - PHASE_START) + 2
        e = exact_by_phase[p]
        expected_end = round(e['calc_start'] + e['demand'] - e['weekly_capacity'], 2)
        sheet_end = float(ws.cell(row, 6).value)
        if not math.isclose(sheet_end, expected_end, rel_tol=0.0, abs_tol=1e-6):
            raise RuntimeError(
                f'End backlog mismatch at phase {p}: sheet={sheet_end} expected={expected_end}'
            )

    # 2. Validate summary file
    with open(SUMMARY_PATH, 'r') as f:
        lines = [ln.rstrip('\n') for ln in f.readlines()]

    if len(lines) != 3:
        raise RuntimeError(f'Expected exactly 3 lines in summary, got {len(lines)}')
    if not lines[0].startswith('First_Week_5_Days:'):
        raise RuntimeError('Summary line 1 does not start with First_Week_5_Days:')
    if not lines[1].startswith('First_Week_4_Days:'):
        raise RuntimeError('Summary line 2 does not start with First_Week_4_Days:')
    if not lines[2].startswith('Summary:'):
        raise RuntimeError('Summary line 3 does not start with Summary:')

    summary_text = lines[2][len('Summary:'):].strip()
    # word count and sentence count constraints
    words = [w for w in summary_text.replace('\n', ' ').split(' ') if w]
    if len(words) > 60:
        raise RuntimeError(f'Summary exceeds 60 words: {len(words)} words')
    sentence_count = sum(summary_text.count(ch) for ch in '.!?')
    if sentence_count > 3:
        raise RuntimeError(f'Summary exceeds 3 sentences (punctuation count={sentence_count})')

    # 3. Confirm existing plan identical to schedule plan
    if not filecmp.cmp(EXISTING_PLAN_PATH, SCHEDULE_PLAN_PATH, shallow=False):
        raise RuntimeError('hvac_existing_plan.xlsx is not identical to hvac_schedule_plan.xlsx')


def main():
    demand_map = read_demand_map()
    results, exact = build_results(demand_map)
    print_preview(results)

    first_5, first_4 = find_first_weeks(results)
    print(f"\nFirst_Week_5_Days: {first_5}")
    print(f"First_Week_4_Days: {first_4}")

    write_excel_files(results)
    write_summary(results)
    validate_outputs(results, exact)

    print('\nValidation: OK')
    print(f'Wrote: {EXISTING_PLAN_PATH}')
    print(f'Wrote: {SCHEDULE_PLAN_PATH}')
    print(f'Wrote: {SUMMARY_PATH}')


if __name__ == '__main__':
    main()
